    } else {
      X.stableSince = null;
      if (!valid) reason = 'Waiting for inputs: ' + missing.join(', ');
      else if (!L.sun) reason = 'Night';
      else if (!L.evConn) reason = 'No EV connected';
      else if (!inSolar) reason = 'Charger not in solar mode';
      else if (evCharging) reason = 'EV is charging';
      else if (C.standalone) reason = 'Standalone (no HPVC): the charger starts on solar by itself';
      else if (!hpvcBlocks) reason = 'HPVC is not limiting PV — nothing to release';
    else if (C.legacy && !hpvcSafe) reason = 'HPVC busy (' + (L.hpvcStatus || 'unknown') + ') — waiting for a normal HPVC state';
    else if (C.legacy && !invOk) reason = 'Inverter setup in HPVC not supported for release (Number entity slots only)';
      else if (!C.legacy && !L.relIface) reason = 'HPVC has no external release interface (needs HPVC 1.5.1 or newer)';
      else if (evFull) reason = 'EV already full, no release needed';
      else if (!fcStartOk) reason = 'Forecast too low (< ' + C.pStart + ' W)';
      else if (!irrStartOk) reason = 'Irradiance too low (< ' + C.irrStart + ' W/m²)';
