    else if (now - X.since >= C.ackTimeout) restore('HPVC busy (' + (L.hpvcStatus || 'unknown') + '), no release confirmation within ' + Math.round(C.ackTimeout / 60000) + ' min, request withdrawn');
    else reason = 'Waiting for HPVC to confirm the release (' + Math.round((now - X.since) / 60000) + '/' + Math.round(C.ackTimeout / 60000) + ' min, HPVC: ' + (L.hpvcStatus || 'unknown') + ')';
