if (!C.enabled && reason === '') reason = 'HESC disabled';

// ---- independent Eco charge sessions (forecast vs actual while charging on Eco) ----
const ecoCharging = evCharging && inSolar && L.sun;
// A solar-mode session that starts while there is hardly any sun (forecast AND PV below the hold threshold)
// was started by hand or by a schedule. It is logged, but left out of the advice and the accuracy figures.
// Works for every charger: it only looks at forecast and PV, not at charger-specific states.
if (ecoCharging && !X.eco) {
  X.eco = newSession();
  const num0 = (v) => typeof v === 'number' && isFinite(v);
  X.eco.forced = num0(L.fcNow) && num0(L.pv) && L.fcNow < C.pHold && L.pv < C.pHold;
  if (X.eco.forced) X.day.forcedSessions = (X.day.forcedSessions || 0) + 1; else X.day.ecoSessions++;
}
if (X.eco) integrate(X.eco);
if (!ecoCharging && X.eco) { closeSession(X.eco, 'eco_charge', evFull ? 'ev full' : 'charging ended'); X.eco = null; }

// ---- source reliability: 15-minute daylight intervals (forecast vs actual, irradiance vs PV) ----
// Intervals in which HPVC limited PV are flagged, because curtailed PV says nothing about forecast quality.
const SLOT = 15 * 60000; const slot = Math.floor(now / SLOT) * SLOT;
